export function Logo({ height = 22 }: { height?: number; bold?: boolean }) {
  return (
    <span className="inline-flex items-center" style={{ gap: height * 0.35 }} role="img" aria-label="Letchi">
      <Mark size={Math.round(height * 0.68)} />
      <Wordmark height={height} />
    </span>
  );
}
